Contract AutomatedTellerMachineSystem::ejectCard(): Boolean {

            precondition:
          self.InputCard.oclIsUndefined() = false and self.CardIDValidated = true and self.PasswordValidated = true and self.InputCard.CardStatus.oclIsTypeOf(CardStatus::NORMAL)

            postcondition:
          self.InputCard.CardStatus = CardStatus::SUSPEND and result = true

        }

Contract AutomatedTellerMachineSystem::ejectCard(): Boolean {

            precondition:
          self.InputCard.oclIsUndefined() = false and self.CardIDValidated = true and self.PasswordValidated = true and self.InputCard.CardStatus.oclIsTypeOf(CardStatus::NORMAL)

            postcondition:
          self.InputCard.CardStatus = CardStatus::NORMAL and result = true

        }

Contract SubmitLoanRequestModule::calculateScore(): Integer {

            precondition:
          self.CurrentLoanRequest.oclIsUndefined() = false and self.CurrentLoanRequest.LoanAmount > 0 and self.CurrentLoanRequest.Income > 0

            postcondition:
          self.CurrentLoanRequest.CreditScore = self.CurrentLoanRequest.Income / self.CurrentLoanRequest.LoanAmount * 100 and result = self.CurrentLoanRequest.CreditScore

        }
